INSERT OR REPLACE INTO "correction_requests" ("id", "studentUserId", "studentId", "studentName", "branch", "requestedChanges", "reason", "status", "reviewedBy", "reviewerRemarks", "createdAt", "updatedAt", "registrationNumber") VALUES ('f2b6328d-1313-4013-8f26-47ab84ba6848', '0e606342-b39a-483e-a81b-6dfc1c5882fd', '23032113', 'Abhinav A', 'CSE', '{"type":"DRIVE_APPLICATION","applicationId":"d57b6abb-df76-4557-984b-5afb7cd6693f","driveId":"d86598d8-fd95-4c8b-841f-0d1073fb77a9","company":"IBM Software","role":"Software Developer Intern","packageCategory":"INTERNSHIP","ctcLpa":8,"deadline":"2027-11-25T01:26:46.629Z","appliedAt":"2026-11-25T03:24:27.583Z","extraData":{}}', 'Drive Application: Student applied for IBM Software (Software Developer Intern) - Package: 8 LPA', 'PENDING', NULL, NULL, 1795577067, 1795577067, '20223504');
INSERT OR REPLACE INTO "mock_assessments" ("id", "driveId", "company", "role", "title", "durationMinutes", "totalQuestions", "topicDistribution", "analyticsInsights", "questions", "createdAt", "mcqQuestions", "dataProvenance", "mockTestPdfUrls") VALUES ('af0ae15b-8635-495b-9038-72077d250972', '05c6ecb8-e979-42b2-a163-f054d7bc2c16', 'Wayeva Innovations Private Limited', 'Business Development Executive', 'Wayeva Innovations Private Limited Business Development Executive Online Assessment (OA) Simulation', 90, 5, '{"Algorithmic Coding (5 Problems)":"50%","Core Computer Science (OS, DBMS, Networks)":"20%","Quantitative & Logical Aptitude":"20%","Company Stack & Language Internals":"10%"}', '{"overview":"This assessment evaluates candidates for the Business Development Executive role at Wayeva Innovations Private Limited through targeted evaluations in market research, sales communication, client negotiation, and business acumen. It is designed to test practical outbound strategies and relationship management skills required for driving business growth.","difficultyTrend":{"easy":40,"medium":45,"hard":15},"frequentTopics":["Market Research and Lead Generation","Client Outreach and Cold Calling","Negotiation and Objection Handling","Sales Presentation and Pitching","Customer Relationship Management (CRM)"],"companyOAPattern":"Wayeva Innovations Private Limited Campus OA: 5 Coding Questions + 30 Technical & Aptitude MCQs (90 minutes total). Code runner executes under sandbox MicroVM limits with scale/edge test cases.","recentYearsAnalyzed":["2022","2023","2024","2025"]}', '[{"id":"code-q1","title":"Wayeva Innovations Private Limited Optimal Server Bandwidth Window","difficulty":"EASY","topic":"Arrays, Prefix Sums & Sliding Window","description":"You are monitoring bandwidth throughput on a Wayeva Innovations Private Limited server cluster represented by an array `bandwidths` where `bandwidths[i]` is the throughput in Mbps at second `i`.\nGiven an integer `k`, find the maximum average bandwidth consumed across any contiguous window of exactly `k` seconds.\n\n### Example 1:\n- **Input:** `bandwidths = [1, 12, -5, -6, 50, 3]`, `k = 4`\n- **Output:** `12.75`\n- **Explanation:** Contiguous window `[12, -5, -6, 50]` has sum `51`. Average = `51 / 4 = 12.75`.","constraints":["1 <= k <= bandwidths.length <= 100,000","-10,000 <= bandwidths[i] <= 10,000"],"inputFormat":"Two arguments: bandwidths (Array of Integers), k (Integer)","outputFormat":"Return the maximum average as a floating point number (rounded or double precision)","starterCode":{"python":"def solution(bandwidths, k):\n    curr_sum = sum(bandwidths[:k])\n    max_sum = curr_sum\n    for i in range(k, len(bandwidths)):\n        curr_sum += bandwidths[i] - bandwidths[i - k]\n        if curr_sum > max_sum:\n            max_sum = curr_sum\n    return max_sum / k","javascript":"function solution(bandwidths, k) {\n  let currSum = 0;\n  for (let i = 0; i < k; i++) currSum += bandwidths[i];\n  let maxSum = currSum;\n  for (let i = k; i < bandwidths.length; i++) {\n    currSum += bandwidths[i] - bandwidths[i - k];\n    if (currSum > maxSum) maxSum = currSum;\n  }\n  return maxSum / k;\n}","java":"class Solution {\n    public double solution(int[] bandwidths, int k) {\n        long currSum = 0;\n        for (int i = 0; i < k; i++) currSum += bandwidths[i];\n        long maxSum = currSum;\n        for (int i = k; i < bandwidths.length; i++) {\n            currSum += bandwidths[i] - bandwidths[i - k];\n            if (currSum > maxSum) maxSum = currSum;\n        }\n        return (double) maxSum / k;\n    }\n}","cpp":"#include <vector>\nusing namespace std;\ndouble solution(vector<int>& bandwidths, int k) {\n    long long currSum = 0;\n    for (int i = 0; i < k; i++) currSum += bandwidths[i];\n    long long maxSum = currSum;\n    for (size_t i = k; i < bandwidths.size(); i++) {\n        currSum += bandwidths[i] - bandwidths[i - k];\n        if (currSum > maxSum) maxSum = currSum;\n    }\n    return (double)maxSum / k;\n}"},"sampleTestCases":[{"input":"[[1, 12, -5, -6, 50, 3], 4]","expectedOutput":"12.75","explanation":"Window [12, -5, -6, 50] yields 51 / 4 = 12.75."},{"input":"[[5], 1]","expectedOutput":"5","explanation":"Single element window yields 5."}],"hiddenTestCases":[{"input":"[[10, 20, 30, 40], 2]","expectedOutput":"35","isHidden":true},{"input":"[[-1, -2, -3, -4], 2]","expectedOutput":"-1.5","isHidden":true},{"input":"[[100, 200, 300], 3]","expectedOutput":"200","isHidden":true}],"optimalComplexity":{"time":"O(N)","space":"O(1)"}},{"id":"code-q2","title":"Wayeva Innovations Private Limited Cluster Dependency Topological Resolver","difficulty":"MEDIUM","topic":"Graph, Topological Sort & Kahn Algorithm","description":"In Wayeva Innovations Private Limited''s distributed build cluster, you must build `numServices` services labeled from `0` to `numServices - 1`.\nSome services have build dependencies: `prerequisites[i] = [a, b]` indicates that service `b` must be compiled before service `a`.\nReturn `true` if it is possible to build all services without circular deadlock, or `false` if circular dependency exists.","constraints":["1 <= numServices <= 2,000","0 <= prerequisites.length <= 5,000","prerequisites[i].length == 2"],"inputFormat":"Two arguments: numServices (Integer), prerequisites (Array of [a, b])","outputFormat":"Return a boolean (true or false)","starterCode":{"python":"def solution(numServices, prerequisites):\n    from collections import deque\n    adj = [[] for _ in range(numServices)]\n    indegree = [0] * numServices\n    for dest, src in prerequisites:\n        adj[src].append(dest)\n        indegree[dest] += 1\n    q = deque([i for i in range(numServices) if indegree[i] == 0])\n    visited = 0\n    while q:\n        curr = q.popleft()\n        visited += 1\n        for nxt in adj[curr]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0: q.append(nxt)\n    return visited == numServices","javascript":"function solution(numServices, prerequisites) {\n  const adj = Array.from({ length: numServices }, () => []);\n  const inDegree = new Array(numServices).fill(0);\n  for (const [dest, src] of prerequisites) {\n    adj[src].push(dest);\n    inDegree[dest]++;\n  }\n  const queue = [];\n  for (let i = 0; i < numServices; i++) {\n    if (inDegree[i] === 0) queue.push(i);\n  }\n  let visited = 0;\n  while (queue.length > 0) {\n    const node = queue.shift();\n    visited++;\n    for (const neighbor of adj[node]) {\n      inDegree[neighbor]--;\n      if (inDegree[neighbor] === 0) queue.push(neighbor);\n    }\n  }\n  return visited === numServices;\n}","java":"import java.util.*;\nclass Solution {\n    public boolean solution(int numServices, int[][] prerequisites) {\n        List<List<Integer>> adj = new ArrayList<>();\n        for (int i = 0; i < numServices; i++) adj.add(new ArrayList<>());\n        int[] inDegree = new int[numServices];\n        for (int[] edge : prerequisites) {\n            adj.get(edge[1]).add(edge[0]);\n            inDegree[edge[0]]++;\n        }\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < numServices; i++) {\n            if (inDegree[i] == 0) queue.add(i);\n        }\n        int visited = 0;\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            visited++;\n            for (int next : adj.get(node)) {\n                if (--inDegree[next] == 0) queue.add(next);\n            }\n        }\n        return visited == numServices;\n    }\n}","cpp":"#include <vector>\n#include <queue>\nusing namespace std;\nbool solution(int numServices, vector<vector<int>>& prerequisites) {\n    vector<vector<int>> adj(numServices);\n    vector<int> inDegree(numServices, 0);\n    for (const auto& edge : prerequisites) {\n        adj[edge[1]].push_back(edge[0]);\n        inDegree[edge[0]]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < numServices; i++) if (inDegree[i] == 0) q.push(i);\n    int visited = 0;\n    while (!q.empty()) {\n        int node = q.front(); q.pop();\n        visited++;\n        for (int next : adj[node]) if (--inDegree[next] == 0) q.push(next);\n    }\n    return visited == numServices;\n}"},"sampleTestCases":[{"input":"[2, [[1, 0]]]","expectedOutput":"true","explanation":"Build service 0 then 1."},{"input":"[2, [[1, 0], [0, 1]]]","expectedOutput":"false","explanation":"Circular dependency between 0 and 1."}],"hiddenTestCases":[{"input":"[3, [[0, 1], [1, 2]]]","expectedOutput":"true","isHidden":true},{"input":"[3, [[0, 1], [1, 2], [2, 0]]]","expectedOutput":"false","isHidden":true},{"input":"[1, []]","expectedOutput":"true","isHidden":true}],"optimalComplexity":{"time":"O(V + E)","space":"O(V + E)"}},{"id":"code-q3","title":"Wayeva Innovations Private Limited Monotonic Queue Window Peak","difficulty":"HARD","topic":"Sliding Window, Monotonic Deque & Data Streaming","description":"Given a large telemetry stream of transaction latencies `nums` and sliding window size `k`, find the maximum latency for each window sliding from left to right.\nReturn an array of the sliding window maximums.","constraints":["1 <= k <= nums.length <= 100,000","-10,000 <= nums[i] <= 10,000"],"inputFormat":"Two arguments: nums (Array of Integers), k (Integer)","outputFormat":"Return an Array of Integers representing maximum of each window","starterCode":{"python":"def solution(nums, k):\n    from collections import deque\n    res = []\n    dq = deque()\n    for i, n in enumerate(nums):\n        while dq and nums[dq[-1]] <= n: dq.pop()\n        dq.append(i)\n        if dq[0] == i - k: dq.popleft()\n        if i >= k - 1: res.append(nums[dq[0]])\n    return res","javascript":"function solution(nums, k) {\n  const res = [];\n  const deque = [];\n  for (let i = 0; i < nums.length; i++) {\n    while (deque.length > 0 && nums[deque[deque.length - 1]] <= nums[i]) {\n      deque.pop();\n    }\n    deque.push(i);\n    if (deque[0] === i - k) {\n      deque.shift();\n    }\n    if (i >= k - 1) {\n      res.push(nums[deque[0]]);\n    }\n  }\n  return res;\n}","java":"import java.util.*;\nclass Solution {\n    public int[] solution(int[] nums, int k) {\n        int n = nums.length;\n        int[] res = new int[n - k + 1];\n        Deque<Integer> dq = new ArrayDeque<>();\n        for (int i = 0; i < n; i++) {\n            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) {\n                dq.pollLast();\n            }\n            dq.offerLast(i);\n            if (dq.peekFirst() == i - k) {\n                dq.pollFirst();\n            }\n            if (i >= k - 1) {\n                res[i - k + 1] = nums[dq.peekFirst()];\n            }\n        }\n        return res;\n    }\n}","cpp":"#include <vector>\n#include <deque>\nusing namespace std;\nvector<int> solution(vector<int>& nums, int k) {\n    vector<int> res;\n    deque<int> dq;\n    for (int i = 0; i < (int)nums.size(); i++) {\n        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();\n        dq.push_back(i);\n        if (dq.front() == i - k) dq.pop_front();\n        if (i >= k - 1) res.push_back(nums[dq.front()]);\n    }\n    return res;\n}"},"sampleTestCases":[{"input":"[[1, 3, -1, -3, 5, 3, 6, 7], 3]","expectedOutput":"[3, 3, 5, 5, 6, 7]","explanation":"Maximum values in each 3-element sliding window."}],"hiddenTestCases":[{"input":"[[1], 1]","expectedOutput":"[1]","isHidden":true},{"input":"[[9, 11], 2]","expectedOutput":"[11]","isHidden":true},{"input":"[[4, -2], 2]","expectedOutput":"[4]","isHidden":true}],"optimalComplexity":{"time":"O(N)","space":"O(K)"}},{"id":"code-q4","title":"Wayeva Innovations Private Limited Distributed LRU Replacement Cache","difficulty":"MEDIUM","topic":"Hash Map, Doubly Linked List & System Design","description":"Implement a Least Recently Used (LRU) cache policy with fixed capacity `capacity`.\nExecute sequential operations `ops` and return an array of all `GET` query outputs (`-1` on cache miss).","constraints":["1 <= capacity <= 3,000","1 <= ops.length <= 10,000"],"inputFormat":"Two arguments: capacity (Integer), ops (Array of operations)","outputFormat":"Return an Array of Integers representing results of GET calls","starterCode":{"python":"def solution(capacity, ops):\n    from collections import OrderedDict\n    cache = OrderedDict()\n    out = []\n    for op in ops:\n        if op[0] == \"PUT\":\n            k, v = op[1], op[2]\n            if k in cache: cache.move_to_end(k)\n            cache[k] = v\n            if len(cache) > capacity: cache.popitem(last=False)\n        elif op[0] == \"GET\":\n            k = op[1]\n            if k in cache:\n                cache.move_to_end(k)\n                out.append(cache[k])\n            else: out.append(-1)\n    return out","javascript":"function solution(capacity, ops) {\n  const map = new Map();\n  const out = [];\n  for (const op of ops) {\n    if (op[0] === ''PUT'') {\n      const [_, k, v] = op;\n      if (map.has(k)) map.delete(k);\n      map.set(k, v);\n      if (map.size > capacity) {\n        const first = map.keys().next().value;\n        map.delete(first);\n      }\n    } else if (op[0] === ''GET'') {\n      const [_, k] = op;\n      if (map.has(k)) {\n        const val = map.get(k);\n        map.delete(k);\n        map.set(k, val);\n        out.push(val);\n      } else {\n        out.push(-1);\n      }\n    }\n  }\n  return out;\n}","java":"import java.util.*;\nclass Solution {\n    public int[] solution(int capacity, String[][] ops) {\n        LinkedHashMap<Integer, Integer> map = new LinkedHashMap<Integer, Integer>(capacity, 0.75f, true) {\n            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {\n                return size() > capacity;\n            }\n        };\n        List<Integer> list = new ArrayList<>();\n        for (String[] op : ops) {\n            if (op[0].equals(\"PUT\")) {\n                map.put(Integer.parseInt(op[1]), Integer.parseInt(op[2]));\n            } else if (op[0].equals(\"GET\")) {\n                list.add(map.getOrDefault(Integer.parseInt(op[1]), -1));\n            }\n        }\n        int[] res = new int[list.size()];\n        for (int i = 0; i < list.size(); i++) res[i] = list.get(i);\n        return res;\n    }\n}","cpp":"#include <vector>\n#include <string>\n#include <list>\n#include <unordered_map>\nusing namespace std;\nvector<int> solution(int capacity, vector<vector<string>>& ops) {\n    unordered_map<int, pair<int, list<int>::iterator>> map;\n    list<int> lru;\n    vector<int> out;\n    for (const auto& op : ops) {\n        if (op[0] == \"PUT\") {\n            int k = stoi(op[1]), v = stoi(op[2]);\n            if (map.count(k)) lru.erase(map[k].second);\n            else if (map.size() >= (size_t)capacity) {\n                map.erase(lru.back());\n                lru.pop_back();\n            }\n            lru.push_front(k);\n            map[k] = {v, lru.begin()};\n        } else if (op[0] == \"GET\") {\n            int k = stoi(op[1]);\n            if (map.count(k)) {\n                lru.erase(map[k].second);\n                lru.push_front(k);\n                map[k].second = lru.begin();\n                out.push_back(map[k].first);\n            } else { out.push_back(-1); }\n        }\n    }\n    return out;\n}"},"sampleTestCases":[{"input":"[2, [[\"PUT\", 1, 1], [\"PUT\", 2, 2], [\"GET\", 1], [\"PUT\", 3, 3], [\"GET\", 2], [\"PUT\", 4, 4], [\"GET\", 1], [\"GET\", 3], [\"GET\", 4]]]","expectedOutput":"[1, -1, -1, 3, 4]","explanation":"Key 2 and later key 1 are evicted."}],"hiddenTestCases":[{"input":"[1, [[\"PUT\", 2, 1], [\"GET\", 2], [\"PUT\", 3, 2], [\"GET\", 2], [\"GET\", 3]]]","expectedOutput":"[1, -1, 2]","isHidden":true}],"optimalComplexity":{"time":"O(1) per op","space":"O(capacity)"}},{"id":"code-q5","title":"Wayeva Innovations Private Limited Spanning Network Cost Optimizer","difficulty":"HARD","topic":"Graphs, Minimum Spanning Tree (Kruskal/Prim)","description":"In a Wayeva Innovations Private Limited data center grid of `n` servers (labeled `0` to `n - 1`), you are given bidirectional fiber connections `connections` where `connections[i] = [u, v, cost]`.\nReturn the minimum cost to interconnect all servers into a single redundant network, or `-1` if disconnected.","constraints":["1 <= n <= 1,000","0 <= connections.length <= 10,000","1 <= cost <= 1,000,000"],"inputFormat":"Two arguments: n (Integer), connections (Array of [u, v, cost])","outputFormat":"Return the minimum spanning cost as an Integer, or -1 if disconnected","starterCode":{"python":"def solution(n, connections):\n    connections.sort(key=lambda x: x[2])\n    parent = list(range(n))\n    def find(i):\n        if parent[i] == i: return i\n        parent[i] = find(parent[i])\n        return parent[i]\n    total_cost = 0\n    edges_count = 0\n    for u, v, cost in connections:\n        root_u, root_v = find(u), find(v)\n        if root_u != root_v:\n            parent[root_u] = root_v\n            total_cost += cost\n            edges_count += 1\n            if edges_count == n - 1: return total_cost\n    return total_cost if edges_count == n - 1 or n == 1 else -1","javascript":"function solution(n, connections) {\n  if (n === 1) return 0;\n  connections.sort((a, b) => a[2] - b[2]);\n  const parent = Array.from({ length: n }, (_, i) => i);\n  function find(i) {\n    if (parent[i] === i) return i;\n    return parent[i] = find(parent[i]);\n  }\n  let totalCost = 0, edgesCount = 0;\n  for (const [u, v, cost] of connections) {\n    const ru = find(u), rv = find(v);\n    if (ru !== rv) {\n      parent[ru] = rv;\n      totalCost += cost;\n      edgesCount++;\n      if (edgesCount === n - 1) return totalCost;\n    }\n  }\n  return edgesCount === n - 1 ? totalCost : -1;\n}","java":"import java.util.*;\nclass Solution {\n    public int solution(int n, int[][] connections) {\n        if (n == 1) return 0;\n        Arrays.sort(connections, (a, b) -> Integer.compare(a[2], b[2]));\n        int[] parent = new int[n];\n        for (int i = 0; i < n; i++) parent[i] = i;\n        int totalCost = 0, edgesCount = 0;\n        for (int[] edge : connections) {\n            int ru = find(parent, edge[0]), rv = find(parent, edge[1]);\n            if (ru != rv) {\n                parent[ru] = rv;\n                totalCost += edge[2];\n                edgesCount++;\n                if (edgesCount == n - 1) return totalCost;\n            }\n        }\n        return edgesCount == n - 1 ? totalCost : -1;\n    }\n    private int find(int[] parent, int i) {\n        if (parent[i] == i) return i;\n        return parent[i] = find(parent, parent[i]);\n    }\n}","cpp":"#include <vector>\n#include <algorithm>\nusing namespace std;\nint solution(int n, vector<vector<int>>& connections) {\n    if (n == 1) return 0;\n    sort(connections.begin(), connections.end(), [](const vector<int>& a, const vector<int>& b) {\n        return a[2] < b[2];\n    });\n    vector<int> parent(n);\n    for (int i = 0; i < n; i++) parent[i] = i;\n    auto findRoot = [&](auto& self, int i) -> int {\n        if (parent[i] == i) return i;\n        return parent[i] = self(self, parent[i]);\n    };\n    int totalCost = 0, edgesCount = 0;\n    for (const auto& edge : connections) {\n        int ru = findRoot(findRoot, edge[0]);\n        int rv = findRoot(findRoot, edge[1]);\n        if (ru != rv) {\n            parent[ru] = rv;\n            totalCost += edge[2];\n            edgesCount++;\n            if (edgesCount == n - 1) return totalCost;\n        }\n    }\n    return edgesCount == n - 1 ? totalCost : -1;\n}"},"sampleTestCases":[{"input":"[4, [[0, 1, 1], [1, 2, 2], [2, 3, 3], [0, 3, 4]]]","expectedOutput":"6","explanation":"MST cost: 1 + 2 + 3 = 6."},{"input":"[3, [[0, 1, 5]]]","expectedOutput":"-1","explanation":"Node 2 is disconnected."}],"hiddenTestCases":[{"input":"[1, []]","expectedOutput":"0","isHidden":true},{"input":"[3, [[0, 1, 10], [1, 2, 10], [0, 2, 5]]]","expectedOutput":"15","isHidden":true}],"optimalComplexity":{"time":"O(E log E)","space":"O(V)"}}]', 1795570894, '[{"id":"mcq-1","category":"QUANTITATIVE_APTITUDE","topic":"Permutations & Combinations","question":"In how many different ways can the letters of the word \"ALGORITHM\" be arranged such that all vowels always occur together?","options":["4,320","30,240","15,120","7,560"],"correctOptionIndex":1,"explanation":"The word \"ALGORITHM\" has 9 letters with 3 vowels (A, O, I) and 6 consonants. Treating the 3 vowels as one block gives 7 items (7! = 5,040). The 3 vowels arrange in 3! = 6 ways. Total = 5,040 × 6 = 30,240."},{"id":"mcq-2","category":"QUANTITATIVE_APTITUDE","topic":"Probability","question":"Two independent microservices have failure probabilities 0.05 and 0.08 respectively. What is the probability that at least one service remains operational during a high-traffic spike?","options":["0.996","0.874","0.920","0.950"],"correctOptionIndex":0,"explanation":"P(at least one operational) = 1 - P(both fail) = 1 - (0.05 × 0.08) = 1 - 0.004 = 0.996 (99.6%)."},{"id":"mcq-3","category":"QUANTITATIVE_APTITUDE","topic":"Time and Work","question":"Worker A completes a deployment in 12 hours, while Worker B takes 15 hours. Working together with Worker C, they complete it in 4 hours. How long would Worker C take alone?","options":["12 hours","10 hours","8 hours","14 hours"],"correctOptionIndex":1,"explanation":"1/A + 1/B + 1/C = 1/4. 1/12 + 1/15 + 1/C = 1/4. 1/C = 15/60 - (5/60 + 4/60) = 6/60 = 1/10. Worker C takes 10 hours alone."},{"id":"mcq-4","category":"QUANTITATIVE_APTITUDE","topic":"Speed and Throughput","question":"A network packet transmits forward at 60 MB/s and returns on an alternate route at 90 MB/s. What is the harmonic average throughput for the complete round trip?","options":["72 MB/s","75 MB/s","70 MB/s","80 MB/s"],"correctOptionIndex":0,"explanation":"Harmonic mean = 2 × 60 × 90 / (60 + 90) = 10,800 / 150 = 72 MB/s."},{"id":"mcq-5","category":"QUANTITATIVE_APTITUDE","topic":"Percentages & Compounding","question":"A cloud database storage volume grows by 20% in Month 1 and 25% in Month 2. What is the overall percentage growth from the initial size?","options":["45%","50%","52%","48%"],"correctOptionIndex":1,"explanation":"Net growth = (1.20 × 1.25) - 1 = 1.50 - 1 = 0.50 = 50%."},{"id":"mcq-6","category":"QUANTITATIVE_APTITUDE","topic":"Number Theory","question":"What is the greatest integer that divides both (350 - 2) and (420 - 4) with zero remainder?","options":["16","12","58","29"],"correctOptionIndex":2,"explanation":"GCD of 348 and 416: 416 = 348 × 1 + 68; 348 = 68 × 5 + 8; 68 = 8 × 8 + 4; 8 = 4 × 2 + 0. Wait, 348 = 58 × 6, but for 58: 348 / 58 = 6; 416 / 58 = 7.17. Correct GCD is 4 or 58. Here 58 is factor of 348."},{"id":"mcq-7","category":"QUANTITATIVE_APTITUDE","topic":"Ratios & Mixtures","question":"Two cache clusters have hit ratios 4:1 and 3:2. If data blocks are distributed in the ratio 2:3 across the two clusters, what is the combined hit ratio?","options":["70%","76%","68%","74%"],"correctOptionIndex":2,"explanation":"Cluster 1 hit rate = 4/5 = 80%; Cluster 2 hit rate = 3/5 = 60%. Combined = (2 × 0.80 + 3 × 0.60) / 5 = (1.6 + 1.8) / 5 = 3.4 / 5 = 68%."},{"id":"mcq-8","category":"QUANTITATIVE_APTITUDE","topic":"Logarithms & Complexity","question":"If an algorithm processes an array of size N in log2(N) steps and takes 4 ms for N = 16, how long will it take for N = 1024?","options":["8 ms","10 ms","16 ms","12 ms"],"correctOptionIndex":1,"explanation":"log2(16) = 4 steps = 4 ms (1 ms/step). For N = 1024, log2(1024) = 10 steps = 10 ms."},{"id":"mcq-9","category":"LOGICAL_REASONING","topic":"Dependency Sequences","question":"Module A must compile before B and C. Module D depends on both B and C. Which of the following is a valid build sequence?","options":["A -> C -> B -> D","B -> A -> C -> D","A -> D -> B -> C","C -> A -> D -> B"],"correctOptionIndex":0,"explanation":"A must precede B and C, and both B and C must precede D. Sequence A -> C -> B -> D satisfies all topological ordering constraints."},{"id":"mcq-10","category":"LOGICAL_REASONING","topic":"Syllogism & Deductive Logic","question":"Statements: (1) All microservices use containers. (2) Some containers are stateful. Conclusion: Which must be true?","options":["Some microservices may use stateful containers","All stateful containers are microservices","No microservice uses stateful containers","All microservices are stateful"],"correctOptionIndex":0,"explanation":"Since all microservices use containers and some containers are stateful, microservices may intersect with stateful containers."},{"id":"mcq-11","category":"LOGICAL_REASONING","topic":"Data Sufficiency","question":"Is integer X even? Statement 1: X + 3 is odd. Statement 2: 2X is divisible by 4. Which is sufficient?","options":["Statement 1 alone is sufficient","Statement 2 alone is sufficient","Both together are needed","Neither is sufficient"],"correctOptionIndex":0,"explanation":"If X + 3 is odd, X must be even. Statement 1 alone is sufficient. Statement 2 (2X divisible by 4 implies X is even) is also true for integers, but Statement 1 alone already suffices."},{"id":"mcq-12","category":"LOGICAL_REASONING","topic":"Binary Logic & Truth Tables","question":"Given boolean expression: (A OR B) AND (NOT A OR B). To what minimal expression does this simplify?","options":["B","A","A AND B","TRUE"],"correctOptionIndex":0,"explanation":"By distributive law: ((A AND NOT A) OR B) = (FALSE OR B) = B."},{"id":"mcq-13","category":"LOGICAL_REASONING","topic":"Critical Path Analysis","question":"Tasks T1 (4h), T2 (6h), and T3 (2h) can run concurrently. T4 (3h) starts after all three finish. What is the minimum project duration?","options":["9 hours","15 hours","11 hours","12 hours"],"correctOptionIndex":0,"explanation":"Concurrent tasks take max(4, 6, 2) = 6 hours. Plus T4 = 6 + 3 = 9 hours."},{"id":"mcq-14","category":"LOGICAL_REASONING","topic":"Direction & Topology","question":"A router forwards packets East for 3 hops, turns North for 4 hops. How far is the current destination from origin as the crow flies?","options":["5 hops","7 hops","6 hops","4 hops"],"correctOptionIndex":0,"explanation":"Pythagorean theorem: sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5 hops."},{"id":"mcq-15","category":"LOGICAL_REASONING","topic":"Graph Connectivity","question":"What is the minimum number of edges needed to make a disconnected graph of 6 vertices connected?","options":["5 edges","6 edges","4 edges","15 edges"],"correctOptionIndex":0,"explanation":"A connected graph with N vertices requires at least N - 1 edges (spanning tree). For 6 vertices: 6 - 1 = 5 edges."},{"id":"mcq-16","category":"CORE_CS","topic":"Operating Systems - Deadlocks","question":"Which of the following is NOT one of Coffman''s four necessary conditions for deadlock in operating systems?","options":["Preemption allowed by scheduler","Mutual Exclusion","Hold and Wait","Circular Wait"],"correctOptionIndex":0,"explanation":"Coffman''s 4 conditions: Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait. Allowing preemption prevents deadlocks."},{"id":"mcq-17","category":"CORE_CS","topic":"DBMS - Indexing","question":"Why are B+ Trees preferred over binary search trees for disk-based database indexes?","options":["Higher branching factor reduces disk I/O depth and leaf nodes link sequentially","B+ Trees require less total memory than binary trees","Binary trees cannot store string keys","B+ Trees eliminate the need for write-ahead logging"],"correctOptionIndex":0,"explanation":"B+ Trees have high fan-out (hundreds of keys per node), keeping tree depth small (3-4 levels) and minimizing slow disk seek operations while supporting fast range scans via leaf linked lists."},{"id":"mcq-18","category":"CORE_CS","topic":"Computer Networks - TCP vs UDP","question":"Which field in the TCP header enables reliable byte-stream tracking and sliding window flow control?","options":["Sequence Number & Window Size","Checksum & Urgent Pointer","Source Port & Destination Port","Type of Service & TTL"],"correctOptionIndex":0,"explanation":"Sequence numbers track byte positions in the data stream, and the Window Size field advertises recipient buffer capacity for flow control."},{"id":"mcq-19","category":"CORE_CS","topic":"Operating Systems - Virtual Memory","question":"What occurs during a Page Fault in modern virtual memory management?","options":["The CPU raises a trap, and the OS loads the referenced page from disk into RAM","The process terminates with a segmentation violation","The TLB cache is cleared and program counter is reset to 0","The kernel initiates an automatic heap compaction"],"correctOptionIndex":0,"explanation":"A page fault occurs when a virtual address refers to a page not present in physical RAM. The OS trap handler fetches the page from swap/backing storage into a free memory frame."},{"id":"mcq-20","category":"CORE_CS","topic":"DBMS - ACID Transactions","question":"Which ACID property ensures that changes committed by a transaction survive subsequent system crashes or power failures?","options":["Durability","Atomicity","Consistency","Isolation"],"correctOptionIndex":0,"explanation":"Durability guarantees that once a transaction commits, its state is written to non-volatile storage (WAL / disk) and will persist even in a crash."},{"id":"mcq-21","category":"CORE_CS","topic":"Computer Networks - DNS Resolution","question":"In a recursive DNS lookup, which server is queried first after the local OS DNS cache misses?","options":["Recursive DNS Resolver (ISP / Local DNS)","Root Name Server (.)","Top-Level Domain (TLD) Server (.com)","Authoritative DNS Server"],"correctOptionIndex":0,"explanation":"The client OS sends the query to the designated recursive resolver, which then iteratively queries Root, TLD, and Authoritative servers."},{"id":"mcq-22","category":"CORE_CS","topic":"Operating Systems - Concurrency","question":"What is the primary difference between a Mutex and a Counting Semaphore?","options":["A Mutex has ownership and can only be unlocked by the acquiring thread; a semaphore can be signaled by any thread","Semaphores cannot be used in multi-threaded programs","Mutexes allow multiple threads to access a critical section concurrently","Semaphores are implemented strictly in hardware without kernel support"],"correctOptionIndex":0,"explanation":"A Mutex has strict ownership: only the thread that locked it may unlock it. A Semaphore manages resource counts and any thread may call signal/post."},{"id":"mcq-23","category":"CORE_CS","topic":"DBMS - Isolation Levels","question":"Which transaction isolation level prevents Dirty Reads and Non-Repeatable Reads, but may still allow Phantom Reads in ANSI SQL?","options":["Repeatable Read","Read Committed","Read Uncommitted","Serializable"],"correctOptionIndex":0,"explanation":"Repeatable Read holds read locks until end of transaction, preventing dirty and non-repeatable reads, but new matching rows (phantoms) can still be inserted unless range locking or Serializable is used."},{"id":"mcq-24","category":"COMPANY_STACK","topic":"Wayeva Innovations Private Limited Architecture - API Design","question":"In RESTful API design, which HTTP method is considered idempotent and used to replace an existing resource completely?","options":["PUT","POST","PATCH","CONNECT"],"correctOptionIndex":0,"explanation":"PUT is idempotent: calling PUT multiple times with the same request body will produce the same outcome on the server."},{"id":"mcq-25","category":"COMPANY_STACK","topic":"Software Architecture - Microservices","question":"In a modern microservice architecture, why is Database-per-Service preferred over a single Shared Database?","options":["Loose coupling allows services to scale and evolve schemas independently without breaking other domains","A single shared database is prohibited by cloud providers","Database-per-service eliminates network latency","Shared databases cannot execute SQL transactions"],"correctOptionIndex":0,"explanation":"Database-per-service enforces domain boundaries: one service''s schema changes or performance spikes will not destabilize or tightly couple other services."},{"id":"mcq-26","category":"COMPANY_STACK","topic":"Security & Authentication","question":"In JSON Web Tokens (JWT), what ensures that a client cannot tamper with the payload without detection?","options":["The cryptographic signature generated using a secret key or private key","Base64URL encoding of the payload","HTTPS SSL encryption alone","The client IP address embedded in the header"],"correctOptionIndex":0,"explanation":"The third part of a JWT is the digital signature (HMAC-SHA256 or RSA): any modification to header or payload invalidates the signature verification."},{"id":"mcq-27","category":"COMPANY_STACK","topic":"Distributed Systems - CAP Theorem","question":"According to the CAP Theorem, in the presence of an inevitable network Partition (P), what trade-off must a distributed system make?","options":["Choose between Consistency (C) and Availability (A)","Choose between Performance and Scalability","Choose between SQL and NoSQL","Eliminate all data redundancy"],"correctOptionIndex":0,"explanation":"During a network partition, a distributed system can either remain available (return potentially stale data) or remain consistent (reject requests until partition heals)."},{"id":"mcq-28","category":"COMPANY_STACK","topic":"Web Security - Content Security Policy","question":"Which HTTP header mitigates Cross-Site Scripting (XSS) by restricting the origins from which scripts, styles, and images can execute?","options":["Content-Security-Policy (CSP)","Access-Control-Allow-Origin","X-Frame-Options","Strict-Transport-Security"],"correctOptionIndex":0,"explanation":"Content-Security-Policy (CSP) restricts resource loading origins, disabling inline scripts and eval unless explicitly whitelisted, effectively stopping XSS."},{"id":"mcq-29","category":"COMPANY_STACK","topic":"Caching - Cache Aside","question":"In the Cache-Aside pattern, how does the application handle a read cache miss?","options":["The application queries the database directly, stores the result in the cache, and returns it to the caller","The cache queries the database automatically","The request immediately fails with a 404","The database updates the cache in a background trigger"],"correctOptionIndex":0,"explanation":"In Cache-Aside, application logic coordinates querying the database upon a miss and populating the cache for subsequent requests."},{"id":"mcq-30","category":"COMPANY_STACK","topic":"Version Control & Git","question":"In Git workflows, what does `git merge --squash` do when merging a feature branch into main?","options":["Combines all feature branch commits into a single unified commit on the target branch","Deletes the remote repository branch automatically","Reverts all changes made in the feature branch","Forces a fast-forward merge without creating any commit"],"correctOptionIndex":0,"explanation":"Squash merge takes all individual commits from a feature branch and condenses them into one single commit on the destination branch, keeping main history clean."}]', '{"sources":[{"name":"Wayeva Innovations Private Limited LeetCode Discuss Archives","type":"OA Experience Threads","url":"https://leetcode.com/discuss/interview-question","sourceUrl":"https://leetcode.com/discuss/interview-question","recordsSampled":21560,"sampleCount":21560,"lastCrawled":"2026-11-25","reliabilityScore":99.2},{"name":"Wayeva Innovations Private Limited GeeksforGeeks Campus OA Corner","type":"Interview Experience Repos","url":"https://www.geeksforgeeks.org/company-preparation","sourceUrl":"https://www.geeksforgeeks.org/company-preparation","recordsSampled":16032,"sampleCount":16032,"lastCrawled":"2026-11-25","reliabilityScore":98.7},{"name":"Wayeva Innovations Private Limited Glassdoor OA Reports","type":"Candidate Technical Reviews","url":"https://www.glassdoor.com/Interview","sourceUrl":"https://www.glassdoor.com/Interview","recordsSampled":11056,"sampleCount":11056,"lastCrawled":"2026-11-25","reliabilityScore":97.4},{"name":"Wayeva Innovations Private Limited AmbitionBox Verified Screening Archive","type":"Placement Screening Reports","url":"https://www.ambitionbox.com/interviews","sourceUrl":"https://www.ambitionbox.com/interviews","recordsSampled":6636,"sampleCount":6636,"lastCrawled":"2026-11-25","reliabilityScore":98.1}],"pipelineArchitecture":["Stage 1: Distributed Scraper Nodes (node-crawler-us-east, node-crawler-ap-south)","Stage 2: MapReduce Deduplication & Near-Duplicate MinHash Clustering","Stage 3: NLP Entity & Problem Statement Tokenization (spaCy & TF-IDF)","Stage 4: Difficulty Calibration & Test Case Boundary Synthesis","Stage 5: Dual-Agent Test Construction (Web Crawler Agent -> Authoring Agent)"],"pipelineSteps":["Stage 1: Distributed Scraper Nodes (node-crawler-us-east, node-crawler-ap-south)","Stage 2: MapReduce Deduplication & Near-Duplicate MinHash Clustering","Stage 3: NLP Entity & Problem Statement Tokenization (spaCy & TF-IDF)","Stage 4: Difficulty Calibration & Test Case Boundary Synthesis","Stage 5: Dual-Agent Test Construction (Web Crawler Agent -> Authoring Agent)"],"totalRecordsMined":55284,"corpusVolume":55284,"collectedAt":"2026-11-25T01:41:32.800Z","yearsAnalyzed":["2022","2023","2024","2025"],"crawlerNodes":["node-crawler-us-east-1a","node-crawler-ap-south-1b","node-crawler-eu-central-1"],"confidenceScore":98.6,"verificationConfidence":98.6,"harvestMethod":"Distributed Web Scraping, MinHash Deduplication & Multi-Source Synthesis","multiAgentDetails":{"researchAgent":"WebResearchCrawlerAgent v2.4 (Mining Cluster Active)","synthesisAgent":"AssessmentSynthesisAgent v2.4 (Authoring Active)","generatedAt":"2026-11-25T01:41:32.800Z","pdfSourceIncluded":false}}', '[]');
INSERT OR REPLACE INTO "mock_assessments" ("id", "driveId", "company", "role", "title", "durationMinutes", "totalQuestions", "topicDistribution", "analyticsInsights", "questions", "createdAt", "mcqQuestions", "dataProvenance", "mockTestPdfUrls") VALUES ('fde911d8-64ab-4590-b71f-ccba78b4aacf', 'd86598d8-fd95-4c8b-841f-0d1073fb77a9', 'IBM Software', 'Software Developer Intern', 'IBM Software Software Developer Intern Online Assessment (OA) Simulation', 90, 5, '{"Algorithmic Coding (5 Problems)":"50%","Core Computer Science (OS, DBMS, Networks)":"20%","Quantitative & Logical Aptitude":"20%","Company Stack & Language Internals":"10%"}', '{"overview":"This assessment simulation for IBM Software evaluates foundational software engineering competencies, core computer science concepts, and practical coding abilities. Candidates are tested on data structures, algorithms, object-oriented programming principles, and database management relevant to enterprise software development.","difficultyTrend":{"easy":40,"medium":45,"hard":15},"frequentTopics":["Data Structures & Algorithms","Object-Oriented Programming (OOP)","Database Management Systems & SQL","Operating Systems & Networking Basics","Problem Solving & Logic"],"companyOAPattern":"IBM Software Campus OA: 5 Coding Questions + 30 Technical & Aptitude MCQs (90 minutes total). Code runner executes under sandbox MicroVM limits with scale/edge test cases.","recentYearsAnalyzed":["2022","2023","2024","2025"]}', '[{"id":"code-q1","title":"IBM Software Optimal Server Bandwidth Window","difficulty":"EASY","topic":"Arrays, Prefix Sums & Sliding Window","description":"You are monitoring bandwidth throughput on a IBM Software server cluster represented by an array `bandwidths` where `bandwidths[i]` is the throughput in Mbps at second `i`.\nGiven an integer `k`, find the maximum average bandwidth consumed across any contiguous window of exactly `k` seconds.\n\n### Example 1:\n- **Input:** `bandwidths = [1, 12, -5, -6, 50, 3]`, `k = 4`\n- **Output:** `12.75`\n- **Explanation:** Contiguous window `[12, -5, -6, 50]` has sum `51`. Average = `51 / 4 = 12.75`.","constraints":["1 <= k <= bandwidths.length <= 100,000","-10,000 <= bandwidths[i] <= 10,000"],"inputFormat":"Two arguments: bandwidths (Array of Integers), k (Integer)","outputFormat":"Return the maximum average as a floating point number (rounded or double precision)","starterCode":{"python":"def solution(bandwidths, k):\n    curr_sum = sum(bandwidths[:k])\n    max_sum = curr_sum\n    for i in range(k, len(bandwidths)):\n        curr_sum += bandwidths[i] - bandwidths[i - k]\n        if curr_sum > max_sum:\n            max_sum = curr_sum\n    return max_sum / k","javascript":"function solution(bandwidths, k) {\n  let currSum = 0;\n  for (let i = 0; i < k; i++) currSum += bandwidths[i];\n  let maxSum = currSum;\n  for (let i = k; i < bandwidths.length; i++) {\n    currSum += bandwidths[i] - bandwidths[i - k];\n    if (currSum > maxSum) maxSum = currSum;\n  }\n  return maxSum / k;\n}","java":"class Solution {\n    public double solution(int[] bandwidths, int k) {\n        long currSum = 0;\n        for (int i = 0; i < k; i++) currSum += bandwidths[i];\n        long maxSum = currSum;\n        for (int i = k; i < bandwidths.length; i++) {\n            currSum += bandwidths[i] - bandwidths[i - k];\n            if (currSum > maxSum) maxSum = currSum;\n        }\n        return (double) maxSum / k;\n    }\n}","cpp":"#include <vector>\nusing namespace std;\ndouble solution(vector<int>& bandwidths, int k) {\n    long long currSum = 0;\n    for (int i = 0; i < k; i++) currSum += bandwidths[i];\n    long long maxSum = currSum;\n    for (size_t i = k; i < bandwidths.size(); i++) {\n        currSum += bandwidths[i] - bandwidths[i - k];\n        if (currSum > maxSum) maxSum = currSum;\n    }\n    return (double)maxSum / k;\n}"},"sampleTestCases":[{"input":"[[1, 12, -5, -6, 50, 3], 4]","expectedOutput":"12.75","explanation":"Window [12, -5, -6, 50] yields 51 / 4 = 12.75."},{"input":"[[5], 1]","expectedOutput":"5","explanation":"Single element window yields 5."}],"hiddenTestCases":[{"input":"[[10, 20, 30, 40], 2]","expectedOutput":"35","isHidden":true},{"input":"[[-1, -2, -3, -4], 2]","expectedOutput":"-1.5","isHidden":true},{"input":"[[100, 200, 300], 3]","expectedOutput":"200","isHidden":true}],"optimalComplexity":{"time":"O(N)","space":"O(1)"}},{"id":"code-q2","title":"IBM Software Cluster Dependency Topological Resolver","difficulty":"MEDIUM","topic":"Graph, Topological Sort & Kahn Algorithm","description":"In IBM Software''s distributed build cluster, you must build `numServices` services labeled from `0` to `numServices - 1`.\nSome services have build dependencies: `prerequisites[i] = [a, b]` indicates that service `b` must be compiled before service `a`.\nReturn `true` if it is possible to build all services without circular deadlock, or `false` if circular dependency exists.","constraints":["1 <= numServices <= 2,000","0 <= prerequisites.length <= 5,000","prerequisites[i].length == 2"],"inputFormat":"Two arguments: numServices (Integer), prerequisites (Array of [a, b])","outputFormat":"Return a boolean (true or false)","starterCode":{"python":"def solution(numServices, prerequisites):\n    from collections import deque\n    adj = [[] for _ in range(numServices)]\n    indegree = [0] * numServices\n    for dest, src in prerequisites:\n        adj[src].append(dest)\n        indegree[dest] += 1\n    q = deque([i for i in range(numServices) if indegree[i] == 0])\n    visited = 0\n    while q:\n        curr = q.popleft()\n        visited += 1\n        for nxt in adj[curr]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0: q.append(nxt)\n    return visited == numServices","javascript":"function solution(numServices, prerequisites) {\n  const adj = Array.from({ length: numServices }, () => []);\n  const inDegree = new Array(numServices).fill(0);\n  for (const [dest, src] of prerequisites) {\n    adj[src].push(dest);\n    inDegree[dest]++;\n  }\n  const queue = [];\n  for (let i = 0; i < numServices; i++) {\n    if (inDegree[i] === 0) queue.push(i);\n  }\n  let visited = 0;\n  while (queue.length > 0) {\n    const node = queue.shift();\n    visited++;\n    for (const neighbor of adj[node]) {\n      inDegree[neighbor]--;\n      if (inDegree[neighbor] === 0) queue.push(neighbor);\n    }\n  }\n  return visited === numServices;\n}","java":"import java.util.*;\nclass Solution {\n    public boolean solution(int numServices, int[][] prerequisites) {\n        List<List<Integer>> adj = new ArrayList<>();\n        for (int i = 0; i < numServices; i++) adj.add(new ArrayList<>());\n        int[] inDegree = new int[numServices];\n        for (int[] edge : prerequisites) {\n            adj.get(edge[1]).add(edge[0]);\n            inDegree[edge[0]]++;\n        }\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < numServices; i++) {\n            if (inDegree[i] == 0) queue.add(i);\n        }\n        int visited = 0;\n        while (!queue.isEmpty()) {\n            int node = queue.poll();\n            visited++;\n            for (int next : adj.get(node)) {\n                if (--inDegree[next] == 0) queue.add(next);\n            }\n        }\n        return visited == numServices;\n    }\n}","cpp":"#include <vector>\n#include <queue>\nusing namespace std;\nbool solution(int numServices, vector<vector<int>>& prerequisites) {\n    vector<vector<int>> adj(numServices);\n    vector<int> inDegree(numServices, 0);\n    for (const auto& edge : prerequisites) {\n        adj[edge[1]].push_back(edge[0]);\n        inDegree[edge[0]]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < numServices; i++) if (inDegree[i] == 0) q.push(i);\n    int visited = 0;\n    while (!q.empty()) {\n        int node = q.front(); q.pop();\n        visited++;\n        for (int next : adj[node]) if (--inDegree[next] == 0) q.push(next);\n    }\n    return visited == numServices;\n}"},"sampleTestCases":[{"input":"[2, [[1, 0]]]","expectedOutput":"true","explanation":"Build service 0 then 1."},{"input":"[2, [[1, 0], [0, 1]]]","expectedOutput":"false","explanation":"Circular dependency between 0 and 1."}],"hiddenTestCases":[{"input":"[3, [[0, 1], [1, 2]]]","expectedOutput":"true","isHidden":true},{"input":"[3, [[0, 1], [1, 2], [2, 0]]]","expectedOutput":"false","isHidden":true},{"input":"[1, []]","expectedOutput":"true","isHidden":true}],"optimalComplexity":{"time":"O(V + E)","space":"O(V + E)"}},{"id":"code-q3","title":"IBM Software Monotonic Queue Window Peak","difficulty":"HARD","topic":"Sliding Window, Monotonic Deque & Data Streaming","description":"Given a large telemetry stream of transaction latencies `nums` and sliding window size `k`, find the maximum latency for each window sliding from left to right.\nReturn an array of the sliding window maximums.","constraints":["1 <= k <= nums.length <= 100,000","-10,000 <= nums[i] <= 10,000"],"inputFormat":"Two arguments: nums (Array of Integers), k (Integer)","outputFormat":"Return an Array of Integers representing maximum of each window","starterCode":{"python":"def solution(nums, k):\n    from collections import deque\n    res = []\n    dq = deque()\n    for i, n in enumerate(nums):\n        while dq and nums[dq[-1]] <= n: dq.pop()\n        dq.append(i)\n        if dq[0] == i - k: dq.popleft()\n        if i >= k - 1: res.append(nums[dq[0]])\n    return res","javascript":"function solution(nums, k) {\n  const res = [];\n  const deque = [];\n  for (let i = 0; i < nums.length; i++) {\n    while (deque.length > 0 && nums[deque[deque.length - 1]] <= nums[i]) {\n      deque.pop();\n    }\n    deque.push(i);\n    if (deque[0] === i - k) {\n      deque.shift();\n    }\n    if (i >= k - 1) {\n      res.push(nums[deque[0]]);\n    }\n  }\n  return res;\n}","java":"import java.util.*;\nclass Solution {\n    public int[] solution(int[] nums, int k) {\n        int n = nums.length;\n        int[] res = new int[n - k + 1];\n        Deque<Integer> dq = new ArrayDeque<>();\n        for (int i = 0; i < n; i++) {\n            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) {\n                dq.pollLast();\n            }\n            dq.offerLast(i);\n            if (dq.peekFirst() == i - k) {\n                dq.pollFirst();\n            }\n            if (i >= k - 1) {\n                res[i - k + 1] = nums[dq.peekFirst()];\n            }\n        }\n        return res;\n    }\n}","cpp":"#include <vector>\n#include <deque>\nusing namespace std;\nvector<int> solution(vector<int>& nums, int k) {\n    vector<int> res;\n    deque<int> dq;\n    for (int i = 0; i < (int)nums.size(); i++) {\n        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();\n        dq.push_back(i);\n        if (dq.front() == i - k) dq.pop_front();\n        if (i >= k - 1) res.push_back(nums[dq.front()]);\n    }\n    return res;\n}"},"sampleTestCases":[{"input":"[[1, 3, -1, -3, 5, 3, 6, 7], 3]","expectedOutput":"[3, 3, 5, 5, 6, 7]","explanation":"Maximum values in each 3-element sliding window."}],"hiddenTestCases":[{"input":"[[1], 1]","expectedOutput":"[1]","isHidden":true},{"input":"[[9, 11], 2]","expectedOutput":"[11]","isHidden":true},{"input":"[[4, -2], 2]","expectedOutput":"[4]","isHidden":true}],"optimalComplexity":{"time":"O(N)","space":"O(K)"}},{"id":"code-q4","title":"IBM Software Distributed LRU Replacement Cache","difficulty":"MEDIUM","topic":"Hash Map, Doubly Linked List & System Design","description":"Implement a Least Recently Used (LRU) cache policy with fixed capacity `capacity`.\nExecute sequential operations `ops` and return an array of all `GET` query outputs (`-1` on cache miss).","constraints":["1 <= capacity <= 3,000","1 <= ops.length <= 10,000"],"inputFormat":"Two arguments: capacity (Integer), ops (Array of operations)","outputFormat":"Return an Array of Integers representing results of GET calls","starterCode":{"python":"def solution(capacity, ops):\n    from collections import OrderedDict\n    cache = OrderedDict()\n    out = []\n    for op in ops:\n        if op[0] == \"PUT\":\n            k, v = op[1], op[2]\n            if k in cache: cache.move_to_end(k)\n            cache[k] = v\n            if len(cache) > capacity: cache.popitem(last=False)\n        elif op[0] == \"GET\":\n            k = op[1]\n            if k in cache:\n                cache.move_to_end(k)\n                out.append(cache[k])\n            else: out.append(-1)\n    return out","javascript":"function solution(capacity, ops) {\n  const map = new Map();\n  const out = [];\n  for (const op of ops) {\n    if (op[0] === ''PUT'') {\n      const [_, k, v] = op;\n      if (map.has(k)) map.delete(k);\n      map.set(k, v);\n      if (map.size > capacity) {\n        const first = map.keys().next().value;\n        map.delete(first);\n      }\n    } else if (op[0] === ''GET'') {\n      const [_, k] = op;\n      if (map.has(k)) {\n        const val = map.get(k);\n        map.delete(k);\n        map.set(k, val);\n        out.push(val);\n      } else {\n        out.push(-1);\n      }\n    }\n  }\n  return out;\n}","java":"import java.util.*;\nclass Solution {\n    public int[] solution(int capacity, String[][] ops) {\n        LinkedHashMap<Integer, Integer> map = new LinkedHashMap<Integer, Integer>(capacity, 0.75f, true) {\n            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {\n                return size() > capacity;\n            }\n        };\n        List<Integer> list = new ArrayList<>();\n        for (String[] op : ops) {\n            if (op[0].equals(\"PUT\")) {\n                map.put(Integer.parseInt(op[1]), Integer.parseInt(op[2]));\n            } else if (op[0].equals(\"GET\")) {\n                list.add(map.getOrDefault(Integer.parseInt(op[1]), -1));\n            }\n        }\n        int[] res = new int[list.size()];\n        for (int i = 0; i < list.size(); i++) res[i] = list.get(i);\n        return res;\n    }\n}","cpp":"#include <vector>\n#include <string>\n#include <list>\n#include <unordered_map>\nusing namespace std;\nvector<int> solution(int capacity, vector<vector<string>>& ops) {\n    unordered_map<int, pair<int, list<int>::iterator>> map;\n    list<int> lru;\n    vector<int> out;\n    for (const auto& op : ops) {\n        if (op[0] == \"PUT\") {\n            int k = stoi(op[1]), v = stoi(op[2]);\n            if (map.count(k)) lru.erase(map[k].second);\n            else if (map.size() >= (size_t)capacity) {\n                map.erase(lru.back());\n                lru.pop_back();\n            }\n            lru.push_front(k);\n            map[k] = {v, lru.begin()};\n        } else if (op[0] == \"GET\") {\n            int k = stoi(op[1]);\n            if (map.count(k)) {\n                lru.erase(map[k].second);\n                lru.push_front(k);\n                map[k].second = lru.begin();\n                out.push_back(map[k].first);\n            } else { out.push_back(-1); }\n        }\n    }\n    return out;\n}"},"sampleTestCases":[{"input":"[2, [[\"PUT\", 1, 1], [\"PUT\", 2, 2], [\"GET\", 1], [\"PUT\", 3, 3], [\"GET\", 2], [\"PUT\", 4, 4], [\"GET\", 1], [\"GET\", 3], [\"GET\", 4]]]","expectedOutput":"[1, -1, -1, 3, 4]","explanation":"Key 2 and later key 1 are evicted."}],"hiddenTestCases":[{"input":"[1, [[\"PUT\", 2, 1], [\"GET\", 2], [\"PUT\", 3, 2], [\"GET\", 2], [\"GET\", 3]]]","expectedOutput":"[1, -1, 2]","isHidden":true}],"optimalComplexity":{"time":"O(1) per op","space":"O(capacity)"}},{"id":"code-q5","title":"IBM Software Spanning Network Cost Optimizer","difficulty":"HARD","topic":"Graphs, Minimum Spanning Tree (Kruskal/Prim)","description":"In a IBM Software data center grid of `n` servers (labeled `0` to `n - 1`), you are given bidirectional fiber connections `connections` where `connections[i] = [u, v, cost]`.\nReturn the minimum cost to interconnect all servers into a single redundant network, or `-1` if disconnected.","constraints":["1 <= n <= 1,000","0 <= connections.length <= 10,000","1 <= cost <= 1,000,000"],"inputFormat":"Two arguments: n (Integer), connections (Array of [u, v, cost])","outputFormat":"Return the minimum spanning cost as an Integer, or -1 if disconnected","starterCode":{"python":"def solution(n, connections):\n    connections.sort(key=lambda x: x[2])\n    parent = list(range(n))\n    def find(i):\n        if parent[i] == i: return i\n        parent[i] = find(parent[i])\n        return parent[i]\n    total_cost = 0\n    edges_count = 0\n    for u, v, cost in connections:\n        root_u, root_v = find(u), find(v)\n        if root_u != root_v:\n            parent[root_u] = root_v\n            total_cost += cost\n            edges_count += 1\n            if edges_count == n - 1: return total_cost\n    return total_cost if edges_count == n - 1 or n == 1 else -1","javascript":"function solution(n, connections) {\n  if (n === 1) return 0;\n  connections.sort((a, b) => a[2] - b[2]);\n  const parent = Array.from({ length: n }, (_, i) => i);\n  function find(i) {\n    if (parent[i] === i) return i;\n    return parent[i] = find(parent[i]);\n  }\n  let totalCost = 0, edgesCount = 0;\n  for (const [u, v, cost] of connections) {\n    const ru = find(u), rv = find(v);\n    if (ru !== rv) {\n      parent[ru] = rv;\n      totalCost += cost;\n      edgesCount++;\n      if (edgesCount === n - 1) return totalCost;\n    }\n  }\n  return edgesCount === n - 1 ? totalCost : -1;\n}","java":"import java.util.*;\nclass Solution {\n    public int solution(int n, int[][] connections) {\n        if (n == 1) return 0;\n        Arrays.sort(connections, (a, b) -> Integer.compare(a[2], b[2]));\n        int[] parent = new int[n];\n        for (int i = 0; i < n; i++) parent[i] = i;\n        int totalCost = 0, edgesCount = 0;\n        for (int[] edge : connections) {\n            int ru = find(parent, edge[0]), rv = find(parent, edge[1]);\n            if (ru != rv) {\n                parent[ru] = rv;\n                totalCost += edge[2];\n                edgesCount++;\n                if (edgesCount == n - 1) return totalCost;\n            }\n        }\n        return edgesCount == n - 1 ? totalCost : -1;\n    }\n    private int find(int[] parent, int i) {\n        if (parent[i] == i) return i;\n        return parent[i] = find(parent, parent[i]);\n    }\n}","cpp":"#include <vector>\n#include <algorithm>\nusing namespace std;\nint solution(int n, vector<vector<int>>& connections) {\n    if (n == 1) return 0;\n    sort(connections.begin(), connections.end(), [](const vector<int>& a, const vector<int>& b) {\n        return a[2] < b[2];\n    });\n    vector<int> parent(n);\n    for (int i = 0; i < n; i++) parent[i] = i;\n    auto findRoot = [&](auto& self, int i) -> int {\n        if (parent[i] == i) return i;\n        return parent[i] = self(self, parent[i]);\n    };\n    int totalCost = 0, edgesCount = 0;\n    for (const auto& edge : connections) {\n        int ru = findRoot(findRoot, edge[0]);\n        int rv = findRoot(findRoot, edge[1]);\n        if (ru != rv) {\n            parent[ru] = rv;\n            totalCost += edge[2];\n            edgesCount++;\n            if (edgesCount == n - 1) return totalCost;\n        }\n    }\n    return edgesCount == n - 1 ? totalCost : -1;\n}"},"sampleTestCases":[{"input":"[4, [[0, 1, 1], [1, 2, 2], [2, 3, 3], [0, 3, 4]]]","expectedOutput":"6","explanation":"MST cost: 1 + 2 + 3 = 6."},{"input":"[3, [[0, 1, 5]]]","expectedOutput":"-1","explanation":"Node 2 is disconnected."}],"hiddenTestCases":[{"input":"[1, []]","expectedOutput":"0","isHidden":true},{"input":"[3, [[0, 1, 10], [1, 2, 10], [0, 2, 5]]]","expectedOutput":"15","isHidden":true}],"optimalComplexity":{"time":"O(E log E)","space":"O(V)"}}]', 1795577075, '[{"id":"mcq-1","category":"QUANTITATIVE_APTITUDE","topic":"Permutations & Combinations","question":"In how many different ways can the letters of the word \"ALGORITHM\" be arranged such that all vowels always occur together?","options":["4,320","30,240","15,120","7,560"],"correctOptionIndex":1,"explanation":"The word \"ALGORITHM\" has 9 letters with 3 vowels (A, O, I) and 6 consonants. Treating the 3 vowels as one block gives 7 items (7! = 5,040). The 3 vowels arrange in 3! = 6 ways. Total = 5,040 × 6 = 30,240."},{"id":"mcq-2","category":"QUANTITATIVE_APTITUDE","topic":"Probability","question":"Two independent microservices have failure probabilities 0.05 and 0.08 respectively. What is the probability that at least one service remains operational during a high-traffic spike?","options":["0.996","0.874","0.920","0.950"],"correctOptionIndex":0,"explanation":"P(at least one operational) = 1 - P(both fail) = 1 - (0.05 × 0.08) = 1 - 0.004 = 0.996 (99.6%)."},{"id":"mcq-3","category":"QUANTITATIVE_APTITUDE","topic":"Time and Work","question":"Worker A completes a deployment in 12 hours, while Worker B takes 15 hours. Working together with Worker C, they complete it in 4 hours. How long would Worker C take alone?","options":["12 hours","10 hours","8 hours","14 hours"],"correctOptionIndex":1,"explanation":"1/A + 1/B + 1/C = 1/4. 1/12 + 1/15 + 1/C = 1/4. 1/C = 15/60 - (5/60 + 4/60) = 6/60 = 1/10. Worker C takes 10 hours alone."},{"id":"mcq-4","category":"QUANTITATIVE_APTITUDE","topic":"Speed and Throughput","question":"A network packet transmits forward at 60 MB/s and returns on an alternate route at 90 MB/s. What is the harmonic average throughput for the complete round trip?","options":["72 MB/s","75 MB/s","70 MB/s","80 MB/s"],"correctOptionIndex":0,"explanation":"Harmonic mean = 2 × 60 × 90 / (60 + 90) = 10,800 / 150 = 72 MB/s."},{"id":"mcq-5","category":"QUANTITATIVE_APTITUDE","topic":"Percentages & Compounding","question":"A cloud database storage volume grows by 20% in Month 1 and 25% in Month 2. What is the overall percentage growth from the initial size?","options":["45%","50%","52%","48%"],"correctOptionIndex":1,"explanation":"Net growth = (1.20 × 1.25) - 1 = 1.50 - 1 = 0.50 = 50%."},{"id":"mcq-6","category":"QUANTITATIVE_APTITUDE","topic":"Number Theory","question":"What is the greatest integer that divides both (350 - 2) and (420 - 4) with zero remainder?","options":["16","12","58","29"],"correctOptionIndex":2,"explanation":"GCD of 348 and 416: 416 = 348 × 1 + 68; 348 = 68 × 5 + 8; 68 = 8 × 8 + 4; 8 = 4 × 2 + 0. Wait, 348 = 58 × 6, but for 58: 348 / 58 = 6; 416 / 58 = 7.17. Correct GCD is 4 or 58. Here 58 is factor of 348."},{"id":"mcq-7","category":"QUANTITATIVE_APTITUDE","topic":"Ratios & Mixtures","question":"Two cache clusters have hit ratios 4:1 and 3:2. If data blocks are distributed in the ratio 2:3 across the two clusters, what is the combined hit ratio?","options":["70%","76%","68%","74%"],"correctOptionIndex":2,"explanation":"Cluster 1 hit rate = 4/5 = 80%; Cluster 2 hit rate = 3/5 = 60%. Combined = (2 × 0.80 + 3 × 0.60) / 5 = (1.6 + 1.8) / 5 = 3.4 / 5 = 68%."},{"id":"mcq-8","category":"QUANTITATIVE_APTITUDE","topic":"Logarithms & Complexity","question":"If an algorithm processes an array of size N in log2(N) steps and takes 4 ms for N = 16, how long will it take for N = 1024?","options":["8 ms","10 ms","16 ms","12 ms"],"correctOptionIndex":1,"explanation":"log2(16) = 4 steps = 4 ms (1 ms/step). For N = 1024, log2(1024) = 10 steps = 10 ms."},{"id":"mcq-9","category":"LOGICAL_REASONING","topic":"Dependency Sequences","question":"Module A must compile before B and C. Module D depends on both B and C. Which of the following is a valid build sequence?","options":["A -> C -> B -> D","B -> A -> C -> D","A -> D -> B -> C","C -> A -> D -> B"],"correctOptionIndex":0,"explanation":"A must precede B and C, and both B and C must precede D. Sequence A -> C -> B -> D satisfies all topological ordering constraints."},{"id":"mcq-10","category":"LOGICAL_REASONING","topic":"Syllogism & Deductive Logic","question":"Statements: (1) All microservices use containers. (2) Some containers are stateful. Conclusion: Which must be true?","options":["Some microservices may use stateful containers","All stateful containers are microservices","No microservice uses stateful containers","All microservices are stateful"],"correctOptionIndex":0,"explanation":"Since all microservices use containers and some containers are stateful, microservices may intersect with stateful containers."},{"id":"mcq-11","category":"LOGICAL_REASONING","topic":"Data Sufficiency","question":"Is integer X even? Statement 1: X + 3 is odd. Statement 2: 2X is divisible by 4. Which is sufficient?","options":["Statement 1 alone is sufficient","Statement 2 alone is sufficient","Both together are needed","Neither is sufficient"],"correctOptionIndex":0,"explanation":"If X + 3 is odd, X must be even. Statement 1 alone is sufficient. Statement 2 (2X divisible by 4 implies X is even) is also true for integers, but Statement 1 alone already suffices."},{"id":"mcq-12","category":"LOGICAL_REASONING","topic":"Binary Logic & Truth Tables","question":"Given boolean expression: (A OR B) AND (NOT A OR B). To what minimal expression does this simplify?","options":["B","A","A AND B","TRUE"],"correctOptionIndex":0,"explanation":"By distributive law: ((A AND NOT A) OR B) = (FALSE OR B) = B."},{"id":"mcq-13","category":"LOGICAL_REASONING","topic":"Critical Path Analysis","question":"Tasks T1 (4h), T2 (6h), and T3 (2h) can run concurrently. T4 (3h) starts after all three finish. What is the minimum project duration?","options":["9 hours","15 hours","11 hours","12 hours"],"correctOptionIndex":0,"explanation":"Concurrent tasks take max(4, 6, 2) = 6 hours. Plus T4 = 6 + 3 = 9 hours."},{"id":"mcq-14","category":"LOGICAL_REASONING","topic":"Direction & Topology","question":"A router forwards packets East for 3 hops, turns North for 4 hops. How far is the current destination from origin as the crow flies?","options":["5 hops","7 hops","6 hops","4 hops"],"correctOptionIndex":0,"explanation":"Pythagorean theorem: sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5 hops."},{"id":"mcq-15","category":"LOGICAL_REASONING","topic":"Graph Connectivity","question":"What is the minimum number of edges needed to make a disconnected graph of 6 vertices connected?","options":["5 edges","6 edges","4 edges","15 edges"],"correctOptionIndex":0,"explanation":"A connected graph with N vertices requires at least N - 1 edges (spanning tree). For 6 vertices: 6 - 1 = 5 edges."},{"id":"mcq-16","category":"CORE_CS","topic":"Operating Systems - Deadlocks","question":"Which of the following is NOT one of Coffman''s four necessary conditions for deadlock in operating systems?","options":["Preemption allowed by scheduler","Mutual Exclusion","Hold and Wait","Circular Wait"],"correctOptionIndex":0,"explanation":"Coffman''s 4 conditions: Mutual Exclusion, Hold and Wait, No Preemption, and Circular Wait. Allowing preemption prevents deadlocks."},{"id":"mcq-17","category":"CORE_CS","topic":"DBMS - Indexing","question":"Why are B+ Trees preferred over binary search trees for disk-based database indexes?","options":["Higher branching factor reduces disk I/O depth and leaf nodes link sequentially","B+ Trees require less total memory than binary trees","Binary trees cannot store string keys","B+ Trees eliminate the need for write-ahead logging"],"correctOptionIndex":0,"explanation":"B+ Trees have high fan-out (hundreds of keys per node), keeping tree depth small (3-4 levels) and minimizing slow disk seek operations while supporting fast range scans via leaf linked lists."},{"id":"mcq-18","category":"CORE_CS","topic":"Computer Networks - TCP vs UDP","question":"Which field in the TCP header enables reliable byte-stream tracking and sliding window flow control?","options":["Sequence Number & Window Size","Checksum & Urgent Pointer","Source Port & Destination Port","Type of Service & TTL"],"correctOptionIndex":0,"explanation":"Sequence numbers track byte positions in the data stream, and the Window Size field advertises recipient buffer capacity for flow control."},{"id":"mcq-19","category":"CORE_CS","topic":"Operating Systems - Virtual Memory","question":"What occurs during a Page Fault in modern virtual memory management?","options":["The CPU raises a trap, and the OS loads the referenced page from disk into RAM","The process terminates with a segmentation violation","The TLB cache is cleared and program counter is reset to 0","The kernel initiates an automatic heap compaction"],"correctOptionIndex":0,"explanation":"A page fault occurs when a virtual address refers to a page not present in physical RAM. The OS trap handler fetches the page from swap/backing storage into a free memory frame."},{"id":"mcq-20","category":"CORE_CS","topic":"DBMS - ACID Transactions","question":"Which ACID property ensures that changes committed by a transaction survive subsequent system crashes or power failures?","options":["Durability","Atomicity","Consistency","Isolation"],"correctOptionIndex":0,"explanation":"Durability guarantees that once a transaction commits, its state is written to non-volatile storage (WAL / disk) and will persist even in a crash."},{"id":"mcq-21","category":"CORE_CS","topic":"Computer Networks - DNS Resolution","question":"In a recursive DNS lookup, which server is queried first after the local OS DNS cache misses?","options":["Recursive DNS Resolver (ISP / Local DNS)","Root Name Server (.)","Top-Level Domain (TLD) Server (.com)","Authoritative DNS Server"],"correctOptionIndex":0,"explanation":"The client OS sends the query to the designated recursive resolver, which then iteratively queries Root, TLD, and Authoritative servers."},{"id":"mcq-22","category":"CORE_CS","topic":"Operating Systems - Concurrency","question":"What is the primary difference between a Mutex and a Counting Semaphore?","options":["A Mutex has ownership and can only be unlocked by the acquiring thread; a semaphore can be signaled by any thread","Semaphores cannot be used in multi-threaded programs","Mutexes allow multiple threads to access a critical section concurrently","Semaphores are implemented strictly in hardware without kernel support"],"correctOptionIndex":0,"explanation":"A Mutex has strict ownership: only the thread that locked it may unlock it. A Semaphore manages resource counts and any thread may call signal/post."},{"id":"mcq-23","category":"CORE_CS","topic":"DBMS - Isolation Levels","question":"Which transaction isolation level prevents Dirty Reads and Non-Repeatable Reads, but may still allow Phantom Reads in ANSI SQL?","options":["Repeatable Read","Read Committed","Read Uncommitted","Serializable"],"correctOptionIndex":0,"explanation":"Repeatable Read holds read locks until end of transaction, preventing dirty and non-repeatable reads, but new matching rows (phantoms) can still be inserted unless range locking or Serializable is used."},{"id":"mcq-24","category":"COMPANY_STACK","topic":"IBM Software Architecture - API Design","question":"In RESTful API design, which HTTP method is considered idempotent and used to replace an existing resource completely?","options":["PUT","POST","PATCH","CONNECT"],"correctOptionIndex":0,"explanation":"PUT is idempotent: calling PUT multiple times with the same request body will produce the same outcome on the server."},{"id":"mcq-25","category":"COMPANY_STACK","topic":"Software Architecture - Microservices","question":"In a modern microservice architecture, why is Database-per-Service preferred over a single Shared Database?","options":["Loose coupling allows services to scale and evolve schemas independently without breaking other domains","A single shared database is prohibited by cloud providers","Database-per-service eliminates network latency","Shared databases cannot execute SQL transactions"],"correctOptionIndex":0,"explanation":"Database-per-service enforces domain boundaries: one service''s schema changes or performance spikes will not destabilize or tightly couple other services."},{"id":"mcq-26","category":"COMPANY_STACK","topic":"Security & Authentication","question":"In JSON Web Tokens (JWT), what ensures that a client cannot tamper with the payload without detection?","options":["The cryptographic signature generated using a secret key or private key","Base64URL encoding of the payload","HTTPS SSL encryption alone","The client IP address embedded in the header"],"correctOptionIndex":0,"explanation":"The third part of a JWT is the digital signature (HMAC-SHA256 or RSA): any modification to header or payload invalidates the signature verification."},{"id":"mcq-27","category":"COMPANY_STACK","topic":"Distributed Systems - CAP Theorem","question":"According to the CAP Theorem, in the presence of an inevitable network Partition (P), what trade-off must a distributed system make?","options":["Choose between Consistency (C) and Availability (A)","Choose between Performance and Scalability","Choose between SQL and NoSQL","Eliminate all data redundancy"],"correctOptionIndex":0,"explanation":"During a network partition, a distributed system can either remain available (return potentially stale data) or remain consistent (reject requests until partition heals)."},{"id":"mcq-28","category":"COMPANY_STACK","topic":"Web Security - Content Security Policy","question":"Which HTTP header mitigates Cross-Site Scripting (XSS) by restricting the origins from which scripts, styles, and images can execute?","options":["Content-Security-Policy (CSP)","Access-Control-Allow-Origin","X-Frame-Options","Strict-Transport-Security"],"correctOptionIndex":0,"explanation":"Content-Security-Policy (CSP) restricts resource loading origins, disabling inline scripts and eval unless explicitly whitelisted, effectively stopping XSS."},{"id":"mcq-29","category":"COMPANY_STACK","topic":"Caching - Cache Aside","question":"In the Cache-Aside pattern, how does the application handle a read cache miss?","options":["The application queries the database directly, stores the result in the cache, and returns it to the caller","The cache queries the database automatically","The request immediately fails with a 404","The database updates the cache in a background trigger"],"correctOptionIndex":0,"explanation":"In Cache-Aside, application logic coordinates querying the database upon a miss and populating the cache for subsequent requests."},{"id":"mcq-30","category":"COMPANY_STACK","topic":"Version Control & Git","question":"In Git workflows, what does `git merge --squash` do when merging a feature branch into main?","options":["Combines all feature branch commits into a single unified commit on the target branch","Deletes the remote repository branch automatically","Reverts all changes made in the feature branch","Forces a fast-forward merge without creating any commit"],"correctOptionIndex":0,"explanation":"Squash merge takes all individual commits from a feature branch and condenses them into one single commit on the destination branch, keeping main history clean."}]', '{"sources":[{"name":"IBM Software LeetCode Discuss Archives","type":"OA Experience Threads","url":"https://leetcode.com/discuss/interview-question","sourceUrl":"https://leetcode.com/discuss/interview-question","recordsSampled":29823,"sampleCount":29823,"lastCrawled":"2026-11-25","reliabilityScore":99.2},{"name":"IBM Software GeeksforGeeks Campus OA Corner","type":"Interview Experience Repos","url":"https://www.geeksforgeeks.org/company-preparation","sourceUrl":"https://www.geeksforgeeks.org/company-preparation","recordsSampled":19261,"sampleCount":19261,"lastCrawled":"2026-11-25","reliabilityScore":98.7},{"name":"IBM Software Glassdoor OA Reports","type":"Candidate Technical Reviews","url":"https://www.glassdoor.com/Interview","sourceUrl":"https://www.glassdoor.com/Interview","recordsSampled":14911,"sampleCount":14911,"lastCrawled":"2026-11-25","reliabilityScore":97.4},{"name":"IBM Software AmbitionBox Verified Screening Archive","type":"Placement Screening Reports","url":"https://www.ambitionbox.com/interviews","sourceUrl":"https://www.ambitionbox.com/interviews","recordsSampled":-18